"use client";

import * as React from "react";

import { clearDocxDocumentResource } from "@/lib/docx-document-resource";
import { isResourceError, isViewerFormatError } from "@/lib/viewer-errors";
import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource";
import { useIsClient } from "@/components/ui/use-is-client";
import { ViewerErrorBoundary } from "@/components/ui/viewer-error";

import { DocxViewerFallback } from "./docx-viewer-chrome";
import { DocxViewerContent } from "./docx-viewer-content";
import type {
  DocxResourceContentProps,
  DocxViewerHandle,
  DocxViewerProps,
} from "./docx-viewer-types";

export type {
  DocxDocumentSource,
  DocxResourceContentProps,
  DocxTarget,
  DocxViewerHandle,
  DocxViewerProps,
} from "./docx-viewer-types";

export type DocxViewerProviderProps = {
  children: React.ReactNode;
  resource: ViewerResource;
};

export type DocxViewerDocumentProps = Omit<
  DocxResourceContentProps,
  "resource"
>;

export const DocxViewer = React.forwardRef<DocxViewerHandle, DocxViewerProps>(
  function DocxViewer(props, ref) {
    const { source, ...resourceProps } = props;
    const resource = React.useMemo(
      () => createViewerResource(source),
      [source],
    );
    return (
      <DocxResourceContent {...resourceProps} ref={ref} resource={resource} />
    );
  },
);

const DocxViewerResourceContext = React.createContext<ViewerResource | null>(
  null,
);

export function DocxViewerProvider({
  children,
  resource,
}: DocxViewerProviderProps) {
  return (
    <DocxViewerResourceContext.Provider value={resource}>
      {children}
    </DocxViewerResourceContext.Provider>
  );
}

function useDocxViewerResource(): ViewerResource {
  const resource = React.useContext(DocxViewerResourceContext);
  if (!resource) {
    throw new Error(
      "DocxViewerDocument must be used within DocxViewerProvider.",
    );
  }
  return resource;
}

export const DocxViewerDocument = React.forwardRef<
  DocxViewerHandle,
  DocxViewerDocumentProps
>(function DocxViewerDocument(props, ref) {
  const resource = useDocxViewerResource();
  return <DocxResourceContent {...props} ref={ref} resource={resource} />;
});

export const DocxResourceContent = React.forwardRef<
  DocxViewerHandle,
  DocxResourceContentProps
>(function DocxResourceContent(props, ref) {
  const isClient = useIsClient();
  const resource = props.resource;
  if (!isClient) {
    return (
      <DocxViewerFallback
        bare={props.bare}
        className={props.className}
        controls={props.controls}
      />
    );
  }
  return (
    <ViewerErrorBoundary
      bare={props.bare}
      className={props.className}
      download={
        props.controls === false || props.download === false
          ? null
          : resource.originalDownload
      }
      format="docx"
      onRetry={(error) => {
        if (isResourceError(error) || !isViewerFormatError(error)) {
          clearDocxDocumentResource(resource.content);
        }
      }}
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
    >
      <React.Suspense
        fallback={
          <DocxViewerFallback
            bare={props.bare}
            className={props.className}
            controls={props.controls}
          />
        }
      >
        <DocxViewerContent {...props} forwardedRef={ref} resource={resource} />
      </React.Suspense>
    </ViewerErrorBoundary>
  );
});

import {
  detectCategory,
  extensionOf,
  extractName,
  resolveViewerDescriptor,
  textPayloadKey,
  type FileCategory,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source";

export type { FileCategory, ViewerSource };
export type FileViewerFallbackSize = { width: number; height: number };

export interface FileViewerCoreProps {
  source: ViewerSource;
  category?: FileCategory;
  className?: string;
  /** Intrinsic first-frame size for image/TIFF loading skeletons. */
  fallbackFrameSize?: FileViewerFallbackSize;
  /** Intrinsic first-slide size for PPTX loading skeletons. */
  fallbackSlideSize?: FileViewerFallbackSize;
  isolateStyles?: boolean;
}

export type FileDescriptor = ViewerDescriptor;

export function resolveFileDescriptor({
  source,
  category,
}: FileViewerCoreProps): FileDescriptor {
  return resolveViewerDescriptor({
    source,
    category,
  });
}

export function descriptorResetKey(descriptor: FileDescriptor): string {
  return [
    descriptorIdentityResetKey(descriptor),
    descriptor.displayName,
    descriptor.mimeType ?? "",
    descriptor.category,
  ].join("\u0000");
}

function descriptorIdentityResetKey(descriptor: FileDescriptor): string {
  if (
    descriptor.source.kind === "text" &&
    descriptor.source.identityKey == null
  ) {
    return textPayloadKey(descriptor.source.text);
  }
  return descriptor.identityKey;
}

export function isProseTextDescriptor(descriptor: FileDescriptor): boolean {
  if (descriptor.category !== "text") return false;

  const extension = extensionOf(descriptor.fileName);
  if (extension === "txt" || extension === "text") return true;
  return !extension && descriptor.mimeType?.toLowerCase() === "text/plain";
}

export { detectCategory, extensionOf, extractName };

import type { ViewerResource } from "@/lib/viewer-resource";
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source";

export type DocxDocumentSource = UrlViewerSource | BlobViewerSource;

export type DocxTarget =
  | { kind: "text"; text: string }
  | { kind: "cell"; table: number; row: number; column: number };

export interface DocxViewerHandle {
  scrollToTarget: (target: DocxTarget, options?: ScrollIntoViewOptions) => void;
  getViewportElement: () => HTMLDivElement | null;
}

export interface DocxViewerProps {
  source: DocxDocumentSource;
  className?: string;
  scale?: number;
  defaultScale?: number;
  onScaleChange?: (scale: number | null) => void;
  controls?: boolean;
  /** Show download actions in this viewer's controls/error state. */
  download?: boolean;
  highlight?: DocxTarget | null;
  onVisiblePageChange?: (page: number) => void;
  onScrollProgressChange?: (progress: number) => void;
  bare?: boolean;
}

export type DocxResourceContentProps = Omit<DocxViewerProps, "source"> & {
  resource: ViewerResource;
};

import type * as DocxPreview from "docx-preview";

import {
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors";

export const DOCX_MIN_SCALE = 0.25;
export const DOCX_MAX_SCALE = 5;
export const DOCX_ZOOM_STEP = 1.2;

export const DEFAULT_DOCX_PAGE_WIDTH = 816;
export const DEFAULT_DOCX_PAGE_HEIGHT = 1056;

export const DOCX_RENDER_OPTIONS: Partial<DocxPreview.Options> = {
  inWrapper: true,
  breakPages: true,
  ignoreLastRenderedPageBreak: false,
  experimental: true,
  renderHeaders: true,
  renderFooters: true,
  renderFootnotes: true,
};

export const DOCX_SCOPED_STYLES = `
[data-slot="docx-viewer"] .docx-wrapper {
  background: transparent;
  padding: 0;
  gap: 1rem;
}
[data-slot="docx-viewer"] .docx-wrapper > section.docx {
  margin-bottom: 0;
  box-shadow: 0 0 0 1px var(--border), 0 1px 2px 0 rgb(0 0 0 / 0.05);
}`;

export function clampDocxScale(value: number) {
  return clamp(value, DOCX_MIN_SCALE, DOCX_MAX_SCALE);
}

export function normalizeDocxScale(value: number | null | undefined) {
  if (value == null) return null;
  if (Number.isNaN(value)) return 1;
  return clampDocxScale(value);
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function positivePixel(value: number) {
  return Number.isFinite(value) && value > 0 ? value : null;
}

export function toDocxFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions,
): ViewerFormatError {
  if (isViewerFormatError(error)) return error;
  return new ViewerFormatError({
    format: "docx",
    kind: options.kind,
    message: options.message,
    cause: error,
  });
}

import type * as DocxPreview from "docx-preview";

import { ViewerFormatError } from "@/lib/viewer-errors";

import {
  DEFAULT_DOCX_PAGE_HEIGHT,
  DEFAULT_DOCX_PAGE_WIDTH,
  DOCX_RENDER_OPTIONS,
  positivePixel,
} from "./docx-viewer-core";
import {
  createDocxPageLayout,
  type DocxPageLayout,
  type DocxPageWindow,
} from "./docx-viewer-layout";
import {
  readDocxRenderCache,
  readPendingDocxRenderCache,
  writeDocxRenderCache,
  writePendingDocxRenderCache,
  type DocxPageSize,
  type DocxRenderCacheHit,
} from "./docx-viewer-render-cache";

let docxPromise: Promise<typeof DocxPreview> | null = null;

export interface DocxRenderedDocument {
  after: HTMLDivElement;
  before: HTMLDivElement;
  mountedEnd: number;
  mountedStart: number;
  pageLayout: DocxPageLayout;
  pages: readonly HTMLElement[];
  sticky: HTMLElement;
  wrapper: HTMLElement;
}

type DocxRenderBuffer = ArrayBuffer | (() => ArrayBuffer);

export function loadDocxPreview() {
  if (!docxPromise) {
    docxPromise = import("docx-preview").catch((error) => {
      docxPromise = null;
      throw error;
    });
  }
  return docxPromise;
}

export async function renderDocxPreview(
  buffer: ArrayBuffer,
  docxPreviewPromise = loadDocxPreview(),
) {
  const { renderAsync } = await docxPreviewPromise;
  const renderHost = document.createElement("div");
  await renderAsync(buffer, renderHost, undefined, DOCX_RENDER_OPTIONS);
  return renderHost;
}

export async function renderCachedDocxPreview({
  buffer,
  cacheKey,
  docxPreviewPromise,
  getScale,
}: {
  buffer: DocxRenderBuffer;
  cacheKey: string;
  docxPreviewPromise?: Promise<typeof DocxPreview>;
  getScale: () => number;
}): Promise<DocxRenderCacheHit> {
  const cached = readDocxRenderCache(cacheKey);
  if (cached) return cached;

  const pending = readPendingDocxRenderCache(cacheKey);
  if (pending) {
    const pendingEntry = await pending;
    if (pendingEntry) {
      return {
        pageSizes: pendingEntry.pageSizes,
        renderHost: pendingEntry.renderHost.cloneNode(true) as HTMLElement,
      };
    }
  }

  const renderPromise = renderDocxPreview(
    resolveDocxRenderBuffer(buffer),
    docxPreviewPromise ?? loadDocxPreview(),
  ).then((renderHost) => {
    const pageSizes = collectDocxPageSizes(renderHost, getScale());
    const cacheEntry = writeDocxRenderCache({
      key: cacheKey,
      pageSizes,
      renderHost,
    });

    return { cacheEntry, pageSizes, renderHost };
  });
  writePendingDocxRenderCache(
    cacheKey,
    renderPromise.then((result) => result.cacheEntry),
  );

  const result = await renderPromise;
  return {
    pageSizes: result.pageSizes,
    renderHost: result.renderHost,
  };
}

function resolveDocxRenderBuffer(buffer: DocxRenderBuffer) {
  return typeof buffer === "function" ? buffer() : buffer;
}

export function commitDocxRender({
  host,
  pageSizes,
  renderHost,
  scale,
}: {
  host: HTMLElement;
  pageSizes?: readonly DocxPageSize[];
  renderHost: HTMLElement;
  scale: number;
}) {
  const wrapper = renderHost.querySelector<HTMLElement>(".docx-wrapper");
  if (!wrapper) {
    throw new ViewerFormatError({
      format: "docx",
      kind: "render_failed",
      message: "DOCX render produced no pages.",
    });
  }
  const pages = Array.from(
    renderHost.querySelectorAll<HTMLElement>(".docx-wrapper > section.docx"),
  );
  if (!pages.length) {
    throw new ViewerFormatError({
      format: "docx",
      kind: "render_failed",
      message: "DOCX render produced no pages.",
    });
  }
  const z = scale || 1;
  const sizes =
    pageSizes && pageSizes.length === pages.length
      ? pageSizes
      : pages.map((el) => pageSize(el, z));
  pages.forEach((el, i) => {
    el.dataset.pageNumber = String(i + 1);
    el.style.contentVisibility = "auto";
    const [width, height] = sizes[i]!;
    el.style.containIntrinsicSize = `${width}px ${height}px`;
  });
  const pageLayout = createDocxPageLayout(sizes);
  const before = document.createElement("div");
  const after = document.createElement("div");
  before.dataset.slot = "docx-sticky-before-buffer";
  wrapper.dataset.slot = "docx-sticky-window";
  after.dataset.slot = "docx-sticky-after-buffer";
  before.setAttribute("aria-hidden", "true");
  after.setAttribute("aria-hidden", "true");
  wrapper.style.position = "sticky";
  wrapper.style.left = "0";
  wrapper.style.overflow = "visible";
  wrapper.style.width = "100%";

  const staticNodes = Array.from(renderHost.childNodes).filter(
    (node) => node !== wrapper,
  );
  wrapper.replaceChildren();
  host.replaceChildren(...staticNodes, before, wrapper, after);

  const virtualDocument: DocxRenderedDocument = {
    after,
    before,
    mountedEnd: 0,
    mountedStart: 0,
    pageLayout,
    pages,
    sticky: wrapper,
    wrapper,
  };
  return {
    numPages: pages.length,
    pageWidth: pages.length ? sizes[0][0] : null,
    pageLayout,
    virtualDocument,
  };
}

export function projectDocxPages(
  document: DocxRenderedDocument,
  window: DocxPageWindow,
) {
  document.before.style.height = `${window.beforeHeight}px`;
  document.after.style.height = `${window.afterHeight}px`;
  document.sticky.style.top = `${window.stickyOffset}px`;
  document.sticky.style.bottom = `${window.stickyOffset}px`;
  document.sticky.style.height = `${window.renderedHeight}px`;

  const start = window.startIndex;
  const end = window.endIndex;
  if (start === document.mountedStart && end === document.mountedEnd) return;

  if (
    document.mountedEnd <= document.mountedStart ||
    end <= start ||
    end <= document.mountedStart ||
    start >= document.mountedEnd
  ) {
    document.wrapper.replaceChildren(...document.pages.slice(start, end));
    document.mountedStart = start;
    document.mountedEnd = end;
    return;
  }

  for (
    let index = document.mountedStart;
    index < Math.min(start, document.mountedEnd);
    index += 1
  ) {
    document.pages[index]?.remove();
  }
  for (
    let index = Math.max(end, document.mountedStart);
    index < document.mountedEnd;
    index += 1
  ) {
    document.pages[index]?.remove();
  }

  if (start < document.mountedStart) {
    const fragment = globalThis.document.createDocumentFragment();
    for (let index = start; index < document.mountedStart; index += 1) {
      const page = document.pages[index];
      if (page) fragment.append(page);
    }
    document.wrapper.insertBefore(fragment, document.wrapper.firstChild);
  }

  if (end > document.mountedEnd) {
    const fragment = globalThis.document.createDocumentFragment();
    for (
      let index = Math.max(document.mountedEnd, start);
      index < end;
      index += 1
    ) {
      const page = document.pages[index];
      if (page) fragment.append(page);
    }
    document.wrapper.append(fragment);
  }

  document.mountedStart = start;
  document.mountedEnd = end;
}

function collectDocxPageSizes(
  renderHost: HTMLElement,
  scale: number,
): readonly DocxPageSize[] {
  const pages = Array.from(
    renderHost.querySelectorAll<HTMLElement>(".docx-wrapper > section.docx"),
  );
  const z = scale || 1;
  return pages.map((el) => pageSize(el, z));
}

function pageSize(el: HTMLElement, scale: number) {
  const styledWidth = positivePixel(Math.round(cssLengthToPx(el.style.width)));
  const styledHeight = positivePixel(
    Math.round(
      cssLengthToPx(el.style.height) || cssLengthToPx(el.style.minHeight),
    ),
  );
  if (styledWidth && styledHeight) {
    return [styledWidth, styledHeight] as const;
  }

  const r = el.getBoundingClientRect();
  const width = positivePixel(Math.round(r.width / scale));
  const height = positivePixel(Math.round(r.height / scale));
  return [
    styledWidth ?? width ?? DEFAULT_DOCX_PAGE_WIDTH,
    styledHeight ?? height ?? DEFAULT_DOCX_PAGE_HEIGHT,
  ] as const;
}

function cssLengthToPx(value: string) {
  const match = value.trim().match(/^(-?\d*\.?\d+)(px|pt|in|cm|mm|pc)?$/i);
  if (!match) return 0;

  const amount = Number(match[1]);
  if (!Number.isFinite(amount) || amount <= 0) return 0;

  const unit = (match[2] ?? "px").toLowerCase();
  if (unit === "px") return amount;
  if (unit === "pt") return (amount * 96) / 72;
  if (unit === "in") return amount * 96;
  if (unit === "cm") return (amount * 96) / 2.54;
  if (unit === "mm") return (amount * 96) / 25.4;
  if (unit === "pc") return amount * 16;
  return 0;
}

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";

import {
  clampDocxScale,
  DOCX_ZOOM_STEP,
  normalizeDocxScale,
} from "./docx-viewer-core";
import { joinEffectKey } from "@/lib/effect-key";

// The docx stage's own inline padding (p-4 on both sides). Fit-width sizes the
// page to the layout width minus this padding, so the settled stage box
// (page + padding) is an affine unit-slope function of the layout width — the
// shape the fit-width surface motion resolver reprojects.
export const DOCX_STAGE_INLINE_PADDING_PX = 32;

export function useDocxViewerScale({
  defaultScale,
  layoutInlineSize,
  onScaleChange,
  pageWidth,
  resetKey,
  scale: controlledScale,
}: {
  defaultScale?: number;
  layoutInlineSize: number | null;
  onScaleChange?: (scale: number | null) => void;
  pageWidth: number | null;
  resetKey: string;
  scale?: number;
}) {
  const normalizedControlledScale = normalizeDocxScale(controlledScale);
  const isScaleControlled = controlledScale != null;
  const normalizedDefaultScale = normalizeDocxScale(defaultScale);
  const [manualScale, setManualScale] = React.useState<number | null>(
    normalizedDefaultScale,
  );

  useKeyedMountEffect(
    joinEffectKey(["docx-scale-reset", normalizedDefaultScale, resetKey]),
    () => {
      setManualScale(normalizedDefaultScale);
    },
  );

  const fitScale =
    layoutInlineSize && pageWidth
      ? clampDocxScale(
          (layoutInlineSize - DOCX_STAGE_INLINE_PADDING_PX) / pageWidth,
        )
      : 1;
  const isFitWidth = normalizedControlledScale == null && manualScale == null;
  const scale = normalizedControlledScale ?? manualScale ?? fitScale;

  const setViewerScale = React.useCallback(
    (nextScale: number | null) => {
      const normalized =
        nextScale == null ? null : normalizeDocxScale(nextScale);
      if (isScaleControlled) {
        onScaleChange?.(normalized);
        return;
      }
      setManualScale(normalized);
      onScaleChange?.(normalized);
    },
    [isScaleControlled, onScaleChange],
  );

  const zoomIn = React.useCallback(() => {
    setViewerScale(clampDocxScale(scale * DOCX_ZOOM_STEP));
  }, [scale, setViewerScale]);

  const zoomOut = React.useCallback(() => {
    setViewerScale(clampDocxScale(scale / DOCX_ZOOM_STEP));
  }, [scale, setViewerScale]);

  const fitWidth = React.useCallback(() => {
    setViewerScale(null);
  }, [setViewerScale]);

  return {
    fitWidth,
    isFitWidth,
    isScaleControlled,
    scale,
    setViewerScale,
    zoomIn,
    zoomOut,
  };
}

import { clamp } from "./docx-viewer-core";

export const DOCX_PAGE_GAP_PX = 16;
export const DOCX_VIEWER_PADDING_PX = 16;
export const DOCX_READING_MARKER_RATIO = 0.2;
export const DOCX_VIRTUAL_OVERSCAN_PX = 1000;
export const DOCX_FALLBACK_VIEWPORT_HEIGHT_PX = 768;

export interface DocxPageMetric {
  pageNumber: number;
  width: number;
  height: number;
  top: number;
  bottom: number;
}

export interface DocxPageLayout {
  pages: readonly DocxPageMetric[];
  totalHeight: number;
}

export interface DocxPageWindow {
  afterHeight: number;
  beforeHeight: number;
  endIndex: number;
  renderedBottom: number;
  renderedHeight: number;
  renderedTop: number;
  startIndex: number;
  stickyOffset: number;
}

export type DocxReadingAnchor =
  | {
      kind: "top";
    }
  | {
      kind: "page";
      pageNumber: number;
      yPercent: number;
    };

export function createDocxPageLayout(
  sizes: readonly (readonly [number, number])[],
  gap = DOCX_PAGE_GAP_PX,
): DocxPageLayout {
  let top = 0;
  const pages = sizes.map(([width, height], index) => {
    const page: DocxPageMetric = {
      pageNumber: index + 1,
      width,
      height,
      top,
      bottom: top + height,
    };
    top = page.bottom + gap;
    return page;
  });

  return {
    pages,
    totalHeight: pages.length ? pages[pages.length - 1]!.bottom : 0,
  };
}

export function findDocxPageByMarker({
  layout,
  scale,
  scrollTop,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  scale: number;
  scrollTop: number;
  viewportHeight: number;
}) {
  const pages = layout?.pages;
  if (!pages?.length) return null;

  const marker = scrollTop + viewportHeight * DOCX_READING_MARKER_RATIO;
  const y = Math.max(0, (marker - DOCX_VIEWER_PADDING_PX) / safeScale(scale));
  let low = 0;
  let high = pages.length - 1;
  let current = pages[0]!;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const page = pages[mid]!;
    if (page.top <= y) {
      current = page;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return current;
}

export function captureDocxReadingAnchorFromLayout({
  layout,
  scale,
  scrollTop,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  scale: number;
  scrollTop: number;
  viewportHeight: number;
}): DocxReadingAnchor {
  if (scrollTop <= 0) return { kind: "top" };

  const page = findDocxPageByMarker({
    layout,
    scale,
    scrollTop,
    viewportHeight,
  });
  if (!page || page.height <= 0) return { kind: "top" };

  const marker = scrollTop + viewportHeight * DOCX_READING_MARKER_RATIO;
  const y = Math.max(0, (marker - DOCX_VIEWER_PADDING_PX) / safeScale(scale));

  return {
    kind: "page",
    pageNumber: page.pageNumber,
    yPercent: clamp((y - page.top) / page.height, 0, 1),
  };
}

export function restoreDocxReadingAnchorFromLayout({
  anchor,
  layout,
  maxScrollTop,
  scale,
  viewportHeight,
}: {
  anchor: DocxReadingAnchor;
  layout: DocxPageLayout | null;
  maxScrollTop: number;
  scale: number;
  viewportHeight: number;
}) {
  if (anchor.kind === "top") return 0;

  const page = layout?.pages[anchor.pageNumber - 1];
  if (!page || page.height <= 0) return null;

  const y = (page.top + page.height * anchor.yPercent) * safeScale(scale);
  const marker = viewportHeight * DOCX_READING_MARKER_RATIO;
  return clamp(DOCX_VIEWER_PADDING_PX + y - marker, 0, maxScrollTop);
}

export function createDocxPageWindowFromScroll({
  layout,
  overscanPx = DOCX_VIRTUAL_OVERSCAN_PX,
  scale,
  scrollTop,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  overscanPx?: number;
  scale: number;
  scrollTop: number;
  viewportHeight: number;
}): DocxPageWindow {
  const pages = layout?.pages;
  if (!layout || !pages?.length) {
    return emptyDocxPageWindow();
  }

  const z = safeScale(scale);
  const viewHeight = safeViewportHeight(viewportHeight) / z;
  const overscan = Math.max(0, overscanPx) / z;
  const viewTop = Math.max(0, (scrollTop - DOCX_VIEWER_PADDING_PX) / z);
  const windowTop = Math.max(0, viewTop - overscan);
  const windowBottom = Math.min(
    layout.totalHeight,
    viewTop + viewHeight + overscan,
  );

  let startIndex = pages.findIndex((page) => page.bottom >= windowTop);
  if (startIndex === -1) startIndex = pages.length - 1;

  let endIndex = startIndex;
  while (
    endIndex < pages.length &&
    pages[endIndex]!.top <= Math.max(windowBottom, pages[startIndex]!.top)
  ) {
    endIndex += 1;
  }
  if (endIndex === startIndex)
    endIndex = Math.min(pages.length, startIndex + 1);

  return createDocxPageWindowFromRange({
    endIndex,
    layout,
    startIndex,
    viewportHeight: viewHeight,
  });
}

export function createDocxPageWindowForPage({
  layout,
  pageIndex,
  scale,
  viewportHeight,
}: {
  layout: DocxPageLayout | null;
  pageIndex: number;
  scale: number;
  viewportHeight: number;
}): DocxPageWindow {
  const pages = layout?.pages;
  if (!layout || !pages?.length) return emptyDocxPageWindow();
  const safePageIndex = clamp(Math.floor(pageIndex), 0, pages.length - 1);
  return createDocxPageWindowFromRange({
    endIndex: safePageIndex + 1,
    layout,
    startIndex: safePageIndex,
    viewportHeight: safeViewportHeight(viewportHeight) / safeScale(scale),
  });
}

function createDocxPageWindowFromRange({
  endIndex,
  layout,
  startIndex,
  viewportHeight,
}: {
  endIndex: number;
  layout: DocxPageLayout;
  startIndex: number;
  viewportHeight: number;
}): DocxPageWindow {
  const pages = layout.pages;
  const start = clamp(Math.floor(startIndex), 0, pages.length);
  const end = clamp(Math.ceil(endIndex), start, pages.length);
  const first = pages[start];
  const last = pages[end - 1];
  if (!first || !last) return emptyDocxPageWindow();

  const renderedTop = first.top;
  const renderedBottom = last.bottom;
  const renderedHeight = renderedBottom - renderedTop;

  return {
    afterHeight: Math.max(0, layout.totalHeight - renderedBottom),
    beforeHeight: renderedTop,
    endIndex: end,
    renderedBottom,
    renderedHeight,
    renderedTop,
    startIndex: start,
    stickyOffset: -Math.max(0, renderedHeight - Math.max(1, viewportHeight)),
  };
}

function emptyDocxPageWindow(): DocxPageWindow {
  return {
    afterHeight: 0,
    beforeHeight: 0,
    endIndex: 0,
    renderedBottom: 0,
    renderedHeight: 0,
    renderedTop: 0,
    startIndex: 0,
    stickyOffset: 0,
  };
}

function safeViewportHeight(value: number) {
  return Number.isFinite(value) && value > 0
    ? value
    : DOCX_FALLBACK_VIEWPORT_HEIGHT_PX;
}

function safeScale(scale: number) {
  return Number.isFinite(scale) && scale > 0 ? scale : 1;
}

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useMountEffect } from "@/hooks/use-mount-effect";

import { clamp } from "./docx-viewer-core";
import {
  captureDocxReadingAnchorFromLayout,
  findDocxPageByMarker,
  restoreDocxReadingAnchorFromLayout,
  type DocxPageLayout,
  type DocxReadingAnchor,
} from "./docx-viewer-layout";
import { joinEffectKey } from "@/lib/effect-key";

export function useDocxViewerScroll({
  layoutKey,
  pageLayout,
  onScrollProgressChange,
  onVisiblePageChange,
  ready,
  scale,
}: {
  layoutKey: unknown;
  pageLayout: DocxPageLayout | null;
  onScrollProgressChange?: (progress: number) => void;
  onVisiblePageChange?: (page: number) => void;
  ready: boolean;
  scale: number;
}) {
  const scrollViewportRef = React.useRef<HTMLDivElement | null>(null);
  const lastReported = React.useRef(0);
  const latestAnchorRef = React.useRef<DocxReadingAnchor>({ kind: "top" });
  const committedLayoutKeyRef = React.useRef(layoutKey);
  const [currentPage, setCurrentPage] = React.useState(1);
  const scrollFrame = React.useRef(0);

  const resetScroll = React.useCallback(() => {
    setCurrentPage(1);
    lastReported.current = 0;
    latestAnchorRef.current = { kind: "top" };
    if (scrollViewportRef.current) scrollViewportRef.current.scrollTop = 0;
  }, []);

  const measureScroll = React.useCallback(() => {
    scrollFrame.current = 0;
    const viewport = scrollViewportRef.current;
    if (!viewport) return;
    const scrollable = viewport.scrollHeight - viewport.clientHeight;
    onScrollProgressChange?.(
      scrollable > 0 ? clamp(viewport.scrollTop / scrollable, 0, 1) : 0,
    );
    const current =
      findDocxPageByMarker({
        layout: pageLayout,
        scale,
        scrollTop: viewport.scrollTop,
        viewportHeight: viewport.clientHeight,
      })?.pageNumber ?? 1;
    latestAnchorRef.current = captureDocxReadingAnchorFromLayout({
      layout: pageLayout,
      scale,
      scrollTop: viewport.scrollTop,
      viewportHeight: viewport.clientHeight,
    });
    if (current && current !== lastReported.current) {
      lastReported.current = current;
      setCurrentPage(current);
      onVisiblePageChange?.(current);
    }
  }, [onScrollProgressChange, onVisiblePageChange, pageLayout, scale]);

  const handleScroll = React.useCallback(() => {
    if (scrollFrame.current) return;
    scrollFrame.current = -1;
    const requestedFrame = requestAnimationFrame(measureScroll);
    if (scrollFrame.current === -1) scrollFrame.current = requestedFrame;
  }, [measureScroll]);

  useKeyedMountEffect(
    joinEffectKey(["docx-measure", measureScroll, ready]),
    () => {
      if (ready) measureScroll();
    },
  );

  useKeyedLayoutEffect(
    joinEffectKey([
      "docx-layout",
      layoutKey,
      measureScroll,
      pageLayout,
      ready,
      scale,
    ]),
    () => {
      const previousLayoutKey = committedLayoutKeyRef.current;
      committedLayoutKeyRef.current = layoutKey;
      if (!ready) return;
      if (Object.is(previousLayoutKey, layoutKey)) return;

      const viewport = scrollViewportRef.current;
      if (!viewport) return;

      const maxScrollTop = Math.max(
        0,
        viewport.scrollHeight - viewport.clientHeight,
      );
      const restored = restoreDocxReadingAnchorFromLayout({
        anchor: latestAnchorRef.current,
        layout: pageLayout,
        maxScrollTop,
        scale,
        viewportHeight: viewport.clientHeight,
      });
      if (restored != null) viewport.scrollTop = restored;
      measureScroll();
    },
  );

  useMountEffect(() => {
    return () => {
      if (scrollFrame.current > 0) cancelAnimationFrame(scrollFrame.current);
    };
  });

  return {
    currentPage,
    handleScroll,
    measureScroll,
    resetScroll,
    scrollViewportRef,
  };
}

import type { DocxTarget } from "./docx-viewer-types";

export interface DocxRenderIndex {
  pages: readonly HTMLElement[];
  root: HTMLElement;
  text: DocxTextIndex | null;
  cells: Map<string, DocxCellHit> | null;
}

interface DocxTextIndex {
  text: string;
  spans: DocxTextSpan[];
}

interface DocxTextSpan {
  start: number;
  end: number;
  node: Text;
  page: HTMLElement;
  pageNumber: number;
  sourceStartOffset: number;
}

interface DocxTextPoint {
  node: Text;
  offset: number;
  page: HTMLElement;
  pageNumber: number;
}

interface DocxCellHit {
  cell: HTMLElement;
  page: HTMLElement;
  pageNumber: number;
}

export interface DocxResolvedTarget {
  page: HTMLElement;
  pageNumber: number;
  range: Range;
  startContainer: Node;
}

const INLINE_TAGS = new Set([
  "SPAN",
  "A",
  "B",
  "I",
  "EM",
  "STRONG",
  "U",
  "S",
  "STRIKE",
  "DEL",
  "INS",
  "SMALL",
  "BIG",
  "SUB",
  "SUP",
  "MARK",
  "FONT",
  "CODE",
  "ABBR",
  "CITE",
  "Q",
  "TIME",
  "BDI",
  "BDO",
  "WBR",
  "LABEL",
  "VAR",
  "SAMP",
  "KBD",
  "TT",
  "NOBR",
]);

export function buildDocxRenderIndex(
  root: HTMLElement,
  pages: readonly HTMLElement[] = Array.from(
    root.querySelectorAll<HTMLElement>(".docx-wrapper > section.docx"),
  ),
): DocxRenderIndex {
  return {
    pages,
    root,
    text: null,
    cells: null,
  };
}

export function resolveDocxTarget(
  index: DocxRenderIndex,
  target: DocxTarget,
): Range | null {
  return resolveDocxTargetHit(index, target)?.range ?? null;
}

export function resolveDocxTargetHit(
  index: DocxRenderIndex,
  target: DocxTarget,
): DocxResolvedTarget | null {
  if (target.kind === "cell") {
    const cells = index.cells ?? (index.cells = buildDocxCellIndex(index));
    const hit = cells.get(cellKey(target.table, target.row, target.column));
    if (!hit) return null;
    const range = document.createRange();
    range.selectNodeContents(hit.cell);
    return {
      page: hit.page,
      pageNumber: hit.pageNumber,
      range,
      startContainer: hit.cell,
    };
  }

  const needle = normalizeTextTarget(target.text);
  if (!needle) return null;
  const textIndex = index.text ?? (index.text = buildDocxTextIndex(index));
  const idx = textIndex.text.indexOf(needle);
  if (idx === -1) return null;
  const start = findTextPoint(textIndex, idx);
  const end = findTextPoint(textIndex, idx + needle.length - 1);
  if (!start || !end) return null;
  const range = document.createRange();
  range.setStart(start.node, start.offset);
  range.setEnd(end.node, end.offset + 1);
  return {
    page: start.page,
    pageNumber: start.pageNumber,
    range,
    startContainer: start.node,
  };
}

export function targetKey(
  target: DocxTarget | null | undefined,
): string | null {
  if (!target) return null;
  return target.kind === "cell"
    ? `cell:${target.table}:${target.row}:${target.column}`
    : `text:${normalizeTextTarget(target.text)}`;
}

export function normalizeTextTarget(text: string) {
  return text.replace(/\s+/g, " ").trim();
}

function buildDocxCellIndex(index: DocxRenderIndex) {
  const cells = new Map<string, DocxCellHit>();
  let tableIndex = 0;
  index.pages.forEach((page, pageIndex) => {
    const tables = page.querySelectorAll("table");
    tables.forEach((table) => {
      Array.from((table as HTMLTableElement).rows).forEach((row, rowIndex) => {
        Array.from(row.cells).forEach((cell, columnIndex) => {
          if (!hasHiddenAncestor(cell, page)) {
            cells.set(cellKey(tableIndex, rowIndex, columnIndex), {
              cell,
              page,
              pageNumber: pageIndex + 1,
            });
          }
        });
      });
      tableIndex += 1;
    });
  });
  return cells;
}

function buildDocxTextIndex(index: DocxRenderIndex) {
  const pages = index.pages;
  let normalized = "";
  const spans: DocxTextSpan[] = [];
  let prevSpace = false;
  let prevBlock: HTMLElement | null = null;
  let pendingBreak = false;

  const append = (
    text: string,
    node: Text,
    page: HTMLElement,
    pageNumber: number,
    sourceStartOffset: number,
  ) => {
    if (!text) return;
    const start = normalized.length;
    normalized += text;
    spans.push({
      start,
      end: start + text.length,
      node,
      page,
      pageNumber,
      sourceStartOffset,
    });
  };

  pages.forEach((page, pageIndex) => {
    const pageNumber = pageIndex + 1;
    const walker = document.createTreeWalker(
      page,
      NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
    );
    for (let n = walker.nextNode(); n; n = walker.nextNode()) {
      if (n.nodeType === Node.ELEMENT_NODE) {
        const tag = (n as HTMLElement).tagName;
        if (
          (tag === "BR" || tag === "HR") &&
          isDocumentBreakElement(page, n as HTMLElement)
        ) {
          pendingBreak = true;
        }
        continue;
      }
      if (!isDocumentTextNode(page, n as Text)) continue;
      const block = blockContainer((n as Text).parentElement, page);
      const broke = pendingBreak || (prevBlock !== null && block !== prevBlock);
      pendingBreak = false;
      if (broke && !prevSpace && normalized) {
        prevSpace = true;
        append(" ", n as Text, page, pageNumber, 0);
      }
      prevBlock = block;
      const data = (n as Text).data;
      for (let i = 0; i < data.length; i++) {
        if (/\s/.test(data[i])) {
          if (prevSpace) continue;
          prevSpace = true;
          append(" ", n as Text, page, pageNumber, i);
        } else {
          const start = i;
          i += 1;
          while (i < data.length && !/\s/.test(data[i])) i += 1;
          append(data.slice(start, i), n as Text, page, pageNumber, start);
          i -= 1;
          prevSpace = false;
        }
      }
    }
  });
  return { text: normalized, spans };
}

function findTextPoint(
  index: DocxTextIndex,
  offset: number,
): DocxTextPoint | null {
  let low = 0;
  let high = index.spans.length - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const span = index.spans[mid]!;
    if (offset < span.start) {
      high = mid - 1;
    } else if (offset >= span.end) {
      low = mid + 1;
    } else {
      return {
        node: span.node,
        offset: span.sourceStartOffset + offset - span.start,
        page: span.page,
        pageNumber: span.pageNumber,
      };
    }
  }
  return null;
}

function cellKey(table: number, row: number, column: number) {
  return `${table}:${row}:${column}`;
}

function blockContainer(
  el: HTMLElement | null,
  root: HTMLElement,
): HTMLElement {
  let cur = el;
  while (cur && cur !== root && INLINE_TAGS.has(cur.tagName)) {
    cur = cur.parentElement;
  }
  return cur ?? root;
}

function isDocumentTextNode(page: HTMLElement, node: Text) {
  const parent = node.parentElement;
  if (!parent || !page.contains(parent)) return false;
  if (parent.closest("style, script, noscript, template")) return false;
  return !hasHiddenAncestor(parent, page);
}

function isDocumentBreakElement(page: HTMLElement, el: HTMLElement) {
  if (!page.contains(el)) return false;
  return !hasHiddenAncestor(el, page);
}

function hasHiddenAncestor(element: HTMLElement, root: HTMLElement) {
  for (let el: HTMLElement | null = element; el; el = el.parentElement) {
    if (
      el.hidden ||
      el.getAttribute("aria-hidden")?.trim().toLowerCase() === "true"
    ) {
      return true;
    }
    const style =
      typeof window !== "undefined" ? window.getComputedStyle(el) : el.style;
    if (
      style.display === "none" ||
      style.visibility === "hidden" ||
      style.visibility === "collapse" ||
      style.getPropertyValue("content-visibility") === "hidden"
    ) {
      return true;
    }
    if (el === root) break;
  }
  return false;
}

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";

import {
  resolveDocxTarget,
  targetKey,
  type DocxRenderIndex,
} from "./docx-viewer-targets";
import type { DocxTarget } from "./docx-viewer-types";
import { joinEffectKey } from "@/lib/effect-key";

export function useDocxHighlight({
  highlight,
  renderIndex,
  ready,
}: {
  highlight?: DocxTarget | null;
  renderIndex: DocxRenderIndex | null;
  ready: boolean;
}) {
  const highlightName = "docx-src-" + React.useId().replace(/:/g, "");
  const highlightKey = targetKey(highlight);

  useKeyedMountEffect(
    joinEffectKey([
      "docx-highlight",
      highlightKey,
      ready,
      highlightName,
      renderIndex,
    ]),
    () => {
      const registry =
        typeof CSS !== "undefined" && "highlights" in CSS
          ? CSS.highlights
          : null;
      if (!registry || typeof Highlight === "undefined") return;
      const deleteHighlight = () => {
        try {
          registry.delete(highlightName);
        } catch {
          // Highlighting is an enhancement; registry failures must not hide the document.
        }
      };
      if (!highlight || !ready || !renderIndex) {
        deleteHighlight();
        return;
      }
      try {
        const range = resolveDocxTarget(renderIndex, highlight);
        if (range) registry.set(highlightName, new Highlight(range));
        else deleteHighlight();
      } catch {
        deleteHighlight();
      }
      return deleteHighlight;
    },
  );

  return highlightName;
}

